#[cfg(test)]
mod tests {
    use super::*;
    use crate::cpu_profile::{ANY, CPUID};

    /// Every gate constant names the CPUID bit the generated profile advertises (or not) as the catalogue says.
    #[test]
    fn gates_follow_the_cpuid_table() {
        for (name, (leaf, sub, reg, bit), advertised) in GATES {
            let word = CPUID
                .iter()
                .find(|&&(l, s, _)| l == leaf && (s == ANY || s == sub))
                .map(|(_, _, r)| r[reg]);
            assert_eq!(word.is_some_and(|w| w >> bit & 1 != 0), advertised, "{name}");
        }
    }
}
